// Incremented every time a bracketed link (not an image or autolink) is
// produced, so outputLink can tell whether its text contained a link.
let bracketLinkCount = 0;

function outputLink(cap: string[], link: Pick<Tokens.Link, 'href' | 'title'>, raw: string, lexer: _Lexer, rules: Rules): Tokens.Link | Tokens.Image | Tokens.Text {
  const href = link.href;
  const title = link.title || null;
  const text = cap[1].replace(rules.other.outputLinkReplace, '$1');
  const type = cap[0].charAt(0) === '!' ? 'image' : 'link';

  const linkCountBefore = bracketLinkCount;
  const inLink = lexer.state.inLink;
  lexer.state.inLink = true;
  const tokens = lexer.inlineTokens(text);
  lexer.state.inLink = inLink;

  if (type === 'link') {
    if (bracketLinkCount !== linkCountBefore) {
      // Links may not contain other links, at any level of nesting.
      // The opening bracket is literal text and the inner link wins.
      return {
        type: 'text',
        raw: '[',
        text: '[',
      };
    }
    bracketLinkCount++;
  }

  return {
    type,
    raw,
    href,
    title,
    text,
    tokens,
  };
}

